'use strict';

const debug = require('debug')('dsr:connection');
const os = require('os');
const Base = require('tcp-base');

const PROTOCOL_HEADER_LENGTH = 14;
const RESULT_SUCCESS = 0;

// 默认参数
const DEFAULT_OPTIONS = {
  hostname: '',
  port: 9600,
  heartbeatInterval: 5000,
  responseTimeout: 10000,
  protocol: require('./protocol'),
};

// 标识连接的唯一id，自增
let CONNECTION_ID = 1;

/**
 * Dsr 连接对象
 */
class Connection extends Base {
  constructor(options) {
    options = Object.assign({
      headerLength: PROTOCOL_HEADER_LENGTH,
    }, DEFAULT_OPTIONS, options);
    options.host = options.hostname;
    options.port = Number(options.port);
    super(options);

    this._protocol = options.protocol;

    // 记录正在处理中的调用请求
    this._id = CONNECTION_ID++;
    this.clientId = `dsr-${os.hostname()}.${this._id}`;
    this._meta = {
      name: this.name,
      host: this.options.host,
      port: this.options.port,
      // 首次获得响应时间
      firstResponseTime: null,
      // 最后一次获得响应时间
      lastResponseTime: null,
      // 总共发出的请求数
      requests: 0,
      // 总共收到的响应数
      responses: 0,
    };
    this._header = null;
  }

  get hostname() {
    return this.options.hostname;
  }

  getBodyLength(buf) {
    const header = this._headerObj = this._protocol.deserializeHeader(buf);
    return header.connLen + header.appClassNameLen + header.appLen;
  }

  decode(buf) {
    const connObject = this._protocol.deserializeBody(this._headerObj, buf);
    this._headerObj = null;
    return this._handleAppContent(connObject);
  }

  /**
   * 心跳时传给服务端
   * @member {String}
   */
  get clientUrl() {
    return `${this.options.hostname}:${this.options.port}?_SERIALIZETYPE=2&_AUTORECONNECT=false&_HEARBEAT=true&_IDLETIMEOUT=5&_CONNECTTIMEOUT=3000&_TIMEOUT=3000`;
  }

  /**
   * 连接名称
   * @member {String}
   */
  get name() {
    return `Conn#${this._id}(${this.options.hostname}:${this.options.port})`;
  }


  /**
   * @method Connection#sendRequest
   * @param {Object} appContent 业务对象
   * @param {Function} callback 回调函数
   * @return {void}
   */
  sendRequest(appContent, callback) {
    const protocol = this._protocol;
    const connRequest = protocol.createConnectionRequest(appContent);
    const requestId = protocol.getRequestId(connRequest);
    const requestClassName = protocol.getClassName(appContent);

    super.send({
      id: requestId,
      data: this._protocol.encode(connRequest),
    }, callback);
    debug('%s send request %s #%s', this.name, requestClassName, requestId);

    this._meta.requests++;
  }

  /**
   * 发送响应到 Server
   * @method Connection#sendResponse
   * @param {Number} requestId  消息Id，用于关联请求和响应
   * @param {Number} resultCode 请求结果
   * @param {Error} error 异常对象
   * @return {void}
   */
  sendResponse(requestId, resultCode, error) {
    debug('%s send response for #%s', this.name, requestId);
    const connObject = this._protocol.createConnectionResponse(this._socket, requestId, resultCode, error);
    super.send({
      oneway: true,
      id: requestId,
      data: this._protocol.encode(connObject),
    });
    this._meta.responses++;
    this._meta.lastResponseTime = Date();
    if (!this._meta.firstResponseTime) {
      this._meta.firstResponseTime = this._meta.lastResponseTime;
      this.emit('first_response', this._meta);
    }
  }

  get heartBeatPacket() {
    if (!this._heartBeatPacket) {
      this._heartBeatPacket = this.options.protocol.createConnectionHeartBeat(this.clientUrl);
    }
    return this._heartBeatPacket;
  }

  sendHeartBeat() {
    this.sendRequest(this.heartBeatPacket, (err, res) => {
      if (err) {
        return this.close(err);
      }
      if (res !== 1) {
        err = new Error('HeartBeat response expect 1, but got: ' + res);
        err.name = 'ConfigConnectionHeartBeatResponseError';
        return this.close(err);
      }
      this.emit('heartbeat', this._meta);
      debug('heartbeat %j', this._meta);
    });
  }

  _handleAppContent(connObject) {
    const requestId = this._protocol.getRequestId(connObject);
    const isRequest = this._protocol.isRequest(connObject);
    const content = this._protocol.getRequestContent(connObject);
    let err = null;
    if (!isRequest && connObject.result !== RESULT_SUCCESS && connObject.errorMsg) {
      err = new Error(connObject.errorMsg);
      err.javaStack = err.errorStack;
    }

    if (isRequest) {
      this.sendResponse(requestId);
    }

    return {
      isResponse: !isRequest,
      id: requestId,
      error: err,
      data: content,
    };
  }
}

module.exports = Connection;
